// Generated by Pen to Ink. The conditions of locked choices (has_item, not, and, or, compare) as a tree the story
// data holds, and the evaluator that walks it. Plain C++: no Unreal types beyond FString and TArray, so
// npm run test:unreal compiles it. It gives the same answers as the TypeScript evaluator (conditionHolds in gating.ts);
// the NarrativeBridge.StoryData automation test checks that for every locked choice.
#pragma once

#include "CoreMinimal.h"

/** Reads the story's variables for a locked choice's conditions (the story component gives one). */
struct FNarrativeVariableReader
{
    virtual ~FNarrativeVariableReader() = default;
    /** Whether a variable is true (items are Ink Booleans named has_<item>). */
    virtual bool Has(const TCHAR* Name) const = 0;
    virtual bool CompareNumber(const TCHAR* Name, const TCHAR* Op, double Value) const = 0;
    virtual bool CompareText(const TCHAR* Name, const TCHAR* Op, const TCHAR* Value) const = 0;
    virtual bool CompareBool(const TCHAR* Name, const TCHAR* Op, bool Value) const = 0;
};

/** One node of a condition tree. */
struct FNarrativeCondition
{
    enum class EKind { HasItem, Not, And, Or, Compare };
    enum class EOperand { Number, Text, Bool };

    EKind Kind = EKind::And;
    /** HasItem: the Ink variable (has_<item>). Compare: the variable compared. */
    FString Variable;
    /** Compare: ==, !=, <, <=, > or >=. */
    FString Op;
    EOperand Operand = EOperand::Number;
    double Number = 0;
    FString Text;
    bool bBool = false;
    /** Not: the one condition negated. And, Or: all of them. */
    TArray<FNarrativeCondition> Children;

    bool Evaluate(const FNarrativeVariableReader& V) const
    {
        switch (Kind)
        {
        case EKind::HasItem:
            return V.Has(*Variable);
        case EKind::Not:
            return Children.Num() > 0 ? !Children[0].Evaluate(V) : true;
        case EKind::And:
            for (int32 i = 0; i < Children.Num(); ++i)
                if (!Children[i].Evaluate(V)) return false;
            return true;
        case EKind::Or:
            for (int32 i = 0; i < Children.Num(); ++i)
                if (Children[i].Evaluate(V)) return true;
            return false;
        case EKind::Compare:
            switch (Operand)
            {
            case EOperand::Text: return V.CompareText(*Variable, *Op, *Text);
            case EOperand::Bool: return V.CompareBool(*Variable, *Op, bBool);
            default: return V.CompareNumber(*Variable, *Op, Number);
            }
        }
        return false;
    }
};
